export async function propose(args: ProposeArgs): Promise<ProposeResult> {
  const cwd = args.repo ?? process.cwd();
  const root = await repoRoot(cwd);
  const policy: Policy = { ...DEFAULT_POLICY, depth: args.depth ?? DEFAULT_POLICY.depth };

  const degraded: string[] = [];

  // Fail closed: a contract written against an already-modified tree cannot
  // adjudicate anything, because "what changed since" is already polluted.
  const dirty = await dirtyFiles(root);
  if (dirty.length > 0 && !args.allow_dirty) {
    throw new Error(
      `working tree is dirty (${dirty.length} file(s), e.g. ${dirty.slice(0, 3).join(", ")}). ` +
        "A contract proposed against a modified tree cannot adjudicate what the change did. " +
        "Commit or stash first, or re-issue with allow_dirty=true and accept that pre-existing edits will read as in-scope.",
    );
  }
  if (dirty.length > 0) {
    degraded.push(
      `working tree was already dirty at proposal time (${dirty.length} file(s)); pre-existing edits cannot be distinguished from this change`,
    );
  }

  const base = await headSha(root);

  // --head is safe here: propose runs against a clean, committed tree.
  const imp = await impact(root, args.symbol, policy, dirty.length === 0);
  degraded.push(...imp.degraded);

  // Never guess between definitions. Hand back the selector and stop.
  if (imp.data?.disambiguation_required || (imp.data?.focus_matches_total ?? 0) > 1) {
    const candidates = imp.data?.focus_candidates ?? [];
    const list = candidates
      .map((c) => `  ${c.file_path}:${c.start_line}  (${c.kind}) ${c.qualified_name ?? c.name}`)
      .join("\n");
    throw new Error(
      `"${args.symbol}" is ambiguous: ${imp.data?.focus_matches_total} definitions matched.\n` +
        list +
        "\nRe-issue propose_change with a file:line selector, for example symbol: path/to/file.go:123",
    );
  }

  if (!imp.data) {
    throw new Error(
      `could not establish a blast radius for "${args.symbol}".\n` +
        `command: ${imp.provenance.command}\n` +
        `stderr:  ${imp.raw.stderr || imp.raw.error || "(none)"}\n` +
        "No contract was written. entire-guard does not invent a radius it could not measure.",
    );
  }

  const contract = buildContract({
    id: contractId(args.symbol),
    repoRoot: root,
    baseSha: base,
    symbol: args.symbol,
    impact: imp.data,
    impactProvenance: imp.provenance,
    policy,
    degraded,
  });

  // Traps are only meaningful inside the radius we are guarding.
  const radius = new Set(contract.allowed_files.map((f) => f.path));
  const traps = await knownTraps(root, radius);
  contract.known_traps = traps.traps;
  contract.degraded.push(...traps.degraded);

  const file = await saveContract(root, contract);
  return { contract, file };
}

export async function saveContract(repoRoot: string, contract: ChangeContract): Promise<string> {
  const dir = storeDir(repoRoot);
  await mkdir(dir, { recursive: true });
  const file = path.join(dir, `${contract.id}.json`);
  await writeFile(file, JSON.stringify(contract, null, 2), "utf8");
  return file;
}

export function formatContract(contract: ChangeContract, file: string): string {
  const out: string[] = [];
  out.push(`CHANGE CONTRACT ${contract.id}`);
  out.push(`target        ${contract.target.symbol}${contract.target.file ? ` @ ${contract.target.file}:${contract.target.line ?? "?"}` : ""}`);
  out.push(`base commit   ${contract.base_sha}`);
  out.push(`stored at     ${file}`);
  out.push("");

  out.push(`MUST UPDATE (${contract.must_update.length}) - direct callers, deterministic. Not touching these FAILS verification.`);
  out.push(
    bullet(contract.must_update.map((m) => `${m.path}  ->  ${m.symbol}  [${m.relation}]`)),
  );
  out.push("");

  out.push(`ALLOWED FILES (${contract.allowed_files.length}) - the proven blast radius. Editing outside this FAILS verification.`);
  out.push(
    bullet(
      contract.allowed_files.map(
        (f) => `${f.path}  (${f.reason})${f.provenance.confidence === "heuristic" ? "  [heuristic]" : ""}`,
      ),
    ),
  );
  out.push("");

  out.push(`DRIFT CANDIDATES (${contract.drift_candidates.length}) - co-change history, HEURISTIC. Warns only, never fails.`);
  out.push(bullet(contract.drift_candidates.map((d) => `${d.path}  (${d.detail})`)));
  out.push("");

  out.push(`KNOWN TRAPS (${contract.known_traps.length}) - unresolved work recalled from checkpoints. HEURISTIC.`);
  out.push(
    bullet(contract.known_traps.map((t) => `[${t.checkpoint_id}] ${t.text}`)),
  );
  out.push("");

  out.push(`DEGRADED (${contract.degraded.length}) - what could NOT be determined:`);
  out.push(bullet(contract.degraded));
  out.push("");

  const commands = new Set<string>();
  for (const f of contract.allowed_files) commands.add(f.provenance.command);
  for (const t of contract.known_traps) commands.add(t.provenance.command);
  out.push("EVIDENCE - re-run any of these to check this contract yourself:");
  out.push(bullet([...commands]));
  out.push("");
  out.push(`When you are done editing, call verify_change with contract_id "${contract.id}".`);
  return out.join("\n");
}

async function main(): Promise<number> {
  const argv = process.argv.slice(2);
  const command = argv[0];
  const repo = flagValue(argv, "--repo");

  if (command === "propose") {
    const symbol = argv[1];
    if (!symbol || symbol.startsWith("--")) {
      process.stderr.write("propose needs a symbol or file:line selector\n\n" + usage() + "\n");
      return 3;
    }
    const depthRaw = flagValue(argv, "--depth");
    const depth = depthRaw === "1" ? 1 : depthRaw === "2" ? 2 : undefined;
    const { contract, file } = await propose({
      symbol,
      repo,
      depth,
      allow_dirty: argv.includes("--allow-dirty"),
    });
    process.stdout.write(formatContract(contract, file) + "\n");
    return 0;
  }

  if (command === "verify") {
    const maybeId = argv[1] && !argv[1].startsWith("--") ? argv[1] : undefined;
    const verdict = await verify({ contract_id: maybeId, repo });
    if (argv.includes("--json")) {
      process.stdout.write(JSON.stringify(verdict, null, 2) + "\n");
    } else {
      process.stdout.write(formatVerdict(verdict) + "\n");
    }
    return verdict.status === "FAIL" ? 2 : verdict.status === "WARN" ? 1 : 0;
  }

  process.stdout.write(usage() + "\n");
  return command ? 3 : 0;
}

